import {model,shop,money} from './data.js';
import {db,tx,user,uid,mine,notify} from './store.js';
import {esc,params,link,go,a,button,field,select,textarea,submit,form,notice,empty,panel,head,mount,toast,requireUser} from './ui.js';
const context=()=>{const o=mine('orders').find(x=>x.id===params.get('order')),s=o?.suborders.find(x=>x.id===params.get('sub')),i=s?.items.find(x=>x.id===params.get('item'));return {o,s,i};};
async function readEvidence(file){if(!file?.size)return null;if(file.size>2*1024*1024||!['image/png','image/jpeg','application/pdf'].includes(file.type))throw Error('Chỉ nhận PNG/JPEG/PDF tối đa 2 MB.');const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('Không đọc được tệp. Chọn lại bằng chứng rồi thử lại.'));reader.readAsDataURL(file);});return {name:file.name,data};}
export function cases(){if(!requireUser())return;const kind=params.get('new'),{o,s,i}=context();if(kind){
if(['aftersale','review','complaint'].includes(kind)&&(!o||!s||(['aftersale','review'].includes(kind)&&(!i||s.shippingStatus!=='Đã giao')))){mount('Hỗ trợ',empty('Thao tác không hợp lệ','Chọn dòng hàng đã giao trong đơn của bạn để đánh giá/hậu mãi.',a('Lịch sử đơn','orders')));return;}
if(kind==='review'){const r=mine('reviews').find(r=>r.itemId===i.id)||{};mount('Đánh giá',head('Đánh giá sản phẩm & shop',i.name+' · '+shop(s.shopId).name)+form('review',select('Chất lượng sản phẩm','productRating',{5:'5 — Rất tốt',4:'4 — Tốt',3:'3 — Bình thường',2:'2 — Chưa tốt',1:'1 — Kém'},String(r.productRating||5))+select('Dịch vụ shop','shopRating',{5:'5 — Rất tốt',4:'4 — Tốt',3:'3 — Bình thường',2:'2 — Chưa tốt',1:'1 — Kém'},String(r.shopRating||5))+textarea('Nhận xét','text',r.text||'')+submit(r.id?'Cập nhật đánh giá':'Gửi đánh giá'))+(r.history?.length?panel('Lịch sử đánh giá của bạn',r.history.map(h=>'<p>'+new Date(h.at).toLocaleString('vi-VN')+' · '+esc(h.text)+'</p>').join('')):'')+a('Về đơn','order',{id:o.id}));return;}
mount('Gửi hỗ trợ',head(kind==='aftersale'?'Đổi/trả & bảo hành':kind==='report'?'Báo cáo nội dung':'Khiếu nại giao dịch',i?.name||params.get('target')||o?.id||'Hỗ trợ người mua')+(i?notice('Chính sách lúc mua: '+esc(i.policy)):'')+form('case',select('Loại hồ sơ','type',kind==='aftersale'?{return:'Đổi/trả',warranty:'Bảo hành'}:kind==='report'?{report:'Báo cáo nội dung'}:{complaint:'Khiếu nại giao dịch'})+(i?field('Số lượng','qty',1,'number','required min="1" max="'+i.qty+'" step="1"'):'')+field('Lý do','reason','','text','required maxlength="160"')+textarea('Mô tả và kết quả mong muốn','text')+field('Ảnh hoặc PDF bằng chứng (tối đa 2 MB)','evidence','','file','accept="image/png,image/jpeg,application/pdf"')+submit('Gửi hồ sơ demo'))+(o?a('Hủy và về đơn','order',{id:o.id}):a('Hủy','help')));return;}
const c=mine('cases').find(x=>x.id===params.get('id'));if(params.has('id')&&!c){mount('Hồ sơ',empty('Không tìm thấy hồ sơ hoặc không có quyền','Mở hồ sơ của bạn.',a('Danh sách hồ sơ','cases')));return;}
if(!c){mount('Hỗ trợ & hậu mãi',head('Hồ sơ hỗ trợ của tôi','Theo dõi riêng từng món, shop và khoản hoàn.')+(mine('cases').map(c=>'<article class="list-row"><div><h2>'+c.id+'</h2><p>'+esc(c.reason)+' · '+esc(c.status)+'</p></div>'+a('Chi tiết','cases',{id:c.id})+'</article>').join('')||empty('Chưa có hồ sơ','Mở đơn để gửi hậu mãi, hoặc báo cáo từ trang sản phẩm/shop.',a('Lịch sử đơn','orders')))+panel('Sản phẩm đã giao & bảo hành',mine('orders').flatMap(o=>o.suborders.filter(s=>s.shippingStatus==='Đã giao').flatMap(s=>s.items.map(i=>'<p>'+esc(i.name)+' · '+i.serial+' · BH '+i.warranty+' tháng tại '+shop(s.shopId).name+' '+a('Yêu cầu hỗ trợ','cases',{new:'aftersale',order:o.id,sub:s.id,item:i.id})+'</p>'))).join('')||'<p>Chưa có hàng đã giao.</p>'));return;}
mount('Hồ sơ '+c.id,head(c.id,c.type+' · '+c.status)+panel('Nội dung hồ sơ','<p>Đối tượng: '+esc(c.itemId||c.target||c.orderId)+'</p><p>Đơn con: '+esc(c.subId||'Không áp dụng')+' · Shop tiếp nhận: '+esc(c.shopId?shop(c.shopId).name:'Nền tảng')+' · Serial: '+esc(c.serial||'Không áp dụng')+'</p><p>'+esc(c.reason)+'</p><p>'+esc(c.text)+'</p>'+(c.policy?'<p>Cam kết lúc mua: '+esc(c.policy)+'</p>':'')+(c.evidence?'<p><a download="'+esc(c.evidence.name)+'" href="'+c.evidence.data+'">Bằng chứng: '+esc(c.evidence.name)+'</a></p>':'')+'<p>Hồ sơ riêng tư trong phiên demo; báo cáo không đồng nghĩa vi phạm đã xác nhận.</p>')+panel('Tiến trình',c.timeline.map(t=>'<p>'+new Date(t.at).toLocaleString('vi-VN')+' · '+esc(t.text)+'</p>').join(''))+panel('Tài liệu bổ sung',(c.attachments||[]).map(e=>'<p><a download="'+esc(e.name)+'" href="'+e.data+'">'+esc(e.name)+'</a></p>').join('')||'<p>Chưa có tệp bổ sung.</p>')+form('case-message',textarea('Bổ sung thông tin / đề nghị xem xét lại','text')+field('Thêm bằng chứng PNG/JPEG/PDF (tối đa 2 MB)','evidence','','file','accept="image/png,image/jpeg,application/pdf"')+submit('Gửi bổ sung'))+(c.orderId?a('Xem đơn & khoản hoàn','order',{id:c.orderId})+a('Khiếu nại về hồ sơ này','cases',{new:'complaint',order:c.orderId,sub:c.subId,case:c.id}):'')+(c.type==='return'||c.type==='warranty'?panel('Gửi / nhận lại hàng',notice('Địa chỉ tiếp nhận và vận đơn dưới đây là dữ liệu mô phỏng; không gửi hàng thật.')+'<p>'+esc(c.logistics||'Chờ shop xác nhận hướng dẫn gửi hàng. Không tự gửi trước khi được tiếp nhận.')+'</p>'+ (c.replacementSerial?'<p>Serial thay thế demo: '+esc(c.replacementSerial)+'</p>':'')+button('Mô phỏng đã gửi hàng cho shop','case-sent',c.id)+button('Mô phỏng đã nhận lại sản phẩm','case-received',c.id)):'')+'<details class="demo-scenarios"><summary>Mô phỏng phản hồi xử lý</summary>'+button('Yêu cầu bổ sung','case-more',c.id)+button('Tiếp nhận kiểm tra','case-inspect',c.id)+button('Từ chối có lý do','case-reject',c.id)+(c.type==='warranty'?button('Sửa xong, gửi lại','case-repair',c.id)+button('Đổi sản phẩm có serial mới','case-replace',c.id):c.type==='return'?button('Duyệt hoàn tiền','case-refund',c.id):button('Kết luận báo cáo','case-resolve',c.id))+'</details>');}
export function help(){mount('Trợ giúp',head('Mua hàng cùng PCMatch','Hướng dẫn ngắn cho bản demo.')+['Chọn sản phẩm → chọn offer của shop → giỏ → checkout. Không cần qua Builder.','Đơn nhiều shop có phí giao, đơn con và bảo hành riêng. Một shop hủy không tự hủy các shop khác.','Giỏ không giữ tồn. Checkout mô phỏng kiểm tra lại dữ liệu local; không có backend xác minh giá hay thanh toán.','Linh kiện đã có trong Builder không tính vào giỏ. Thiếu dữ liệu kỹ thuật không phải kết quả đạt.','Đổi/trả demo: tiếp nhận trong 7 ngày sau giao. Bảo hành theo số tháng ghi ở từng dòng hàng. Đây là giả định kiểm thử, không phải chính sách thương mại thật.','Dữ liệu demo lưu tại trình duyệt này. Reset demo xóa toàn bộ tài khoản, giỏ và đơn. Chia sẻ cấu hình không hoạt động trên thiết bị khác.'].map((t,i)=>'<details class="help-item" '+(!i?'open':'')+'><summary>'+['Mua linh kiện','Mua nhiều shop','Giá, tồn & thanh toán','Kiểm tra cấu hình','Hậu mãi','Dữ liệu demo'][i]+'</summary><p>'+t+'</p></details>').join('')+'<div class="cluster">'+a('Đơn hàng của tôi','orders')+a('Hồ sơ hỗ trợ','cases')+a('Xem linh kiện','search')+'</div>');}
export function action(act,id){if(!act.startsWith('case-'))return false;if(!requireUser())return true;const c=mine('cases').find(c=>c.id===id);if(!c)throw Error('Không có quyền.');if(c.status==='Đã duyệt đổi/trả — chờ hoàn tiền'||c.status==='Đã nhận lại sản phẩm')throw Error('Hồ sơ đã có kết quả; xem khoản hoàn hoặc gửi đề nghị xem xét lại.');tx(()=>{const statuses={'case-more':'Cần bổ sung bằng chứng','case-inspect':c.type==='warranty'?'Đã nhận — kiểm tra bảo hành':'Đang kiểm tra hồ sơ','case-reject':'Từ chối: bằng chứng demo chưa đủ xác định lỗi','case-repair':'Đã sửa — chờ gửi lại hàng','case-resolve':'Đã xem xét báo cáo — chưa xác nhận vi phạm','case-sent':'Đang gửi hàng cho shop','case-received':'Đã nhận lại sản phẩm','case-replace':'Đã đổi sản phẩm — chờ gửi lại hàng'};
if(act==='case-sent'&&c.status!=='Đang kiểm tra hồ sơ'&&c.status!=='Đã nhận — kiểm tra bảo hành')throw Error('Chờ shop tiếp nhận và hướng dẫn gửi hàng.');if(act==='case-received'&&!['Đã sửa — chờ gửi lại hàng','Đã đổi sản phẩm — chờ gửi lại hàng'].includes(c.status))throw Error('Shop chưa gửi lại sản phẩm.');if(['case-repair','case-replace'].includes(act)&&!['Đang gửi hàng cho shop','Đã nhận — kiểm tra bảo hành'].includes(c.status))throw Error('Cần tiếp nhận kiểm tra trước khi kết luận.');if(act==='case-inspect')c.logistics='Shop tiếp nhận: '+shop(c.shopId||mine('orders').find(o=>o.id===c.orderId)?.suborders.find(s=>s.id===c.subId)?.shopId)?.name+'; chờ vận đơn gửi hàng demo.';if(act==='case-sent')c.logistics='Vận đơn gửi shop demo: '+uid('RETURN');if(['case-repair','case-replace'].includes(act)){c.logistics='Vận đơn gửi lại demo: '+uid('REDELIVERY');if(act==='case-replace')c.replacementSerial=uid('SN');}if(act==='case-refund'){if(c.type!=='return')throw Error('Không phải hồ sơ đổi/trả.');const o=mine('orders').find(o=>o.id===c.orderId),s=o.suborders.find(s=>s.id===c.subId),i=s.items.find(i=>i.id===c.itemId);if(s.refund)throw Error('Đã có khoản hoàn cho đơn con; không tạo trùng.');const allocated=Math.floor(s.discount*i.price*i.qty/s.subtotal);s.refund={id:uid('RF'),amount:i.price*c.qty-Math.floor(allocated*c.qty/i.qty),status:'Đang xử lý',itemId:i.id,qty:c.qty,discount:Math.floor(allocated*c.qty/i.qty),fee:0};c.status='Đã duyệt đổi/trả — chờ hoàn tiền';}else c.status=statuses[act];c.timeline.push({at:Date.now(),text:c.status});notify('Hồ sơ '+c.id+': '+c.status,link('cases',{id:c.id}));});cases();return true;}
export async function submitForm(name,f,d){
if(!['review','case','case-message'].includes(name))return false;if(!requireUser())return true;const {o,s,i}=context();
if(name==='review'){if(!i||s.shippingStatus!=='Đã giao')throw Error('Chỉ đánh giá hàng đã giao của bạn.');tx(st=>{const r=mine('reviews').find(r=>r.itemId===i.id),value={id:r?.id||uid('REV'),userId:user().id,itemId:i.id,modelId:i.modelId,shopId:s.shopId,productRating:+d.productRating,shopRating:+d.shopRating,text:d.text,updatedAt:Date.now(),history:r?[...(r.history||[]),{text:r.text,at:r.updatedAt}]:[]};if(r)Object.assign(r,value);else st.reviews.push(value);});go('model',{id:i.modelId});return true;}
if(name==='case'){if(params.get('new')!=='report'&&(!o||!s))throw Error('Không có quyền với giao dịch.');if(['return','warranty'].includes(d.type)){if(!i||s.shippingStatus!=='Đã giao')throw Error('Chọn hàng đã giao.');if(!Number.isInteger(+d.qty)||+d.qty<1||+d.qty>i.qty)throw Error('Số lượng vượt số đã giao.');if(mine('cases').some(c=>c.itemId===i.id&&!c.status.startsWith('Từ chối')))throw Error('Dòng hàng đã có hồ sơ; mở hồ sơ hiện tại để bổ sung.');if(d.type==='return'&&Date.now()-s.deliveredAt>7*86400000)throw Error('Đã ngoài hạn đổi/trả 7 ngày demo. Chọn bảo hành nếu còn hạn.');if(d.type==='warranty'&&Date.now()-s.deliveredAt>i.warranty*30*86400000)throw Error('Đã hết thời hạn bảo hành demo.');}
const evidence=await readEvidence(f.elements.evidence.files[0]);
const c={id:uid('CASE'),userId:user().id,type:d.type,orderId:o?.id,subId:s?.id,itemId:i?.id,shopId:s?.shopId,serial:i?.serial,parentCaseId:params.get('case'),target:params.get('target'),qty:+d.qty||1,reason:d.reason,text:d.text,policy:i?.policy,evidence,status:'Đã gửi — chờ tiếp nhận',timeline:[{at:Date.now(),text:'Đã gửi hồ sơ demo'}]};tx(st=>{st.cases.push(c);notify('Đã gửi hồ sơ '+c.id,link('cases',{id:c.id}));});go('cases',{id:c.id});return true;}
if(name==='case-message'){const c=mine('cases').find(c=>c.id===params.get('id'));if(!c)throw Error('Không có quyền.');if(!d.text.trim())throw Error('Nhập nội dung bổ sung.');const evidence=await readEvidence(f.elements.evidence.files[0]);tx(()=>{if(evidence){c.attachments||=[];c.attachments.push(evidence);}c.timeline.push({at:Date.now(),text:'Người mua: '+d.text+(evidence?' · Đã bổ sung '+evidence.name:'')});});cases();return true;}return false;
}
